-- 91_rollback.sql (ask_everyday_nov22): undo 21_load exactly. NOT APPLIED. Guarded by the post-load md5 eb8a4923f3ff410be0f19b7014e7c92d.
begin;
lock table pb_ai.kb_chunks in share row exclusive mode;
do $rb$
declare vn int; vm text; vd int;
begin
  select count(*), md5(string_agg(ord||':'||lib||':'||(chunk::text), '|' order by ord)) from pb_ai.kb_chunks where version = 'b3e91f6c47d2' into vn, vm;
  if vn = 3247 and vm = 'f85b4d61df8e54abe6bd391f7317cbd7' then raise notice 'ask_everyday 91_rollback: already rolled back'; return; end if;
  if vn <> 3255 or vm is distinct from 'eb8a4923f3ff410be0f19b7014e7c92d' then raise exception 'FAIL: not the 21_load result (% rows, md5 %)', vn, vm; end if;
  delete from pb_ai.kb_chunks where version = 'b3e91f6c47d2' and ord >= 3247;
  update pb_ai.kb_chunks set chunk = $kb${"id": "business-pm-6", "text": "When extra work can't be priced in advance, it's usually done on time and materials (also called force account on public jobs). A good daily T&M ticket shows: date, project, change or work order number, and a clear description of the work and location (station); each worker's name, trade classification and hours (straight and overtime); each piece of equipment with ID, size, operating hours and standby hours; materials used with quantities (attach invoices); subcontractor and trucking costs; and the owner's representative's signature the same day. Pricing follows the contract: labor at actual wage plus burden, equipment at the contract's rate source (often the Rental Rate Blue Book or a state rate schedule), materials at invoice, plus the contract's markups. Photos before, during and after help. Unsigned or late tickets are the most common reason extra work goes unpaid. Your contract and project specs govern; this is general practice, not legal advice.", "title": "Time and materials (T&M) or force account tickets", "topic": "Business, project management and job costing", "source": "Construction management practice (general; not legal advice; your contract governs)", "confidence": "medium"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 243 and chunk->>'id' = $kb$business-pm-6$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 243; end if;
  update pb_ai.kb_chunks set chunk = $kb${"id": "pipe-ductile-iron-5", "url": "https://www.mcwaneductile.com/upl/downloads/catalog/products/joint-deflection-chart-2d905fa7.pdf", "text": "Ductile iron push-on joints allow deflection at each joint. McWane Ductile's push-on joint chart (18 ft pipe length) lists: sizes 3 through 30 inch, maximum 5 degrees, maximum offset about 19 inches per 18 ft length, approximate curve radius 205 ft; 36 inch, 4 degrees, about 15 inches offset, radius about 260 ft. Other makers and AWWA C600 list similar or more conservative values, especially for larger sizes (some show 3 degrees for the largest pipe). Always use the specific maker's chart for the joint you have; mechanical joints and restrained joints have their own, often smaller, limits. Common design practice is to plan curves using less than the full allowable deflection (DIPRA guidance commonly suggests about 80% of maximum) so there's room for field adjustment. Assemble the joint straight and fully homed, then deflect.", "title": "Ductile iron pipe: push-on joint deflection table", "topic": "Pipe materials: ductile iron", "source": "McWane Ductile, push-on joint deflection chart", "confidence": "high"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 1697 and chunk->>'id' = $kb$pipe-ductile-iron-5$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 1697; end if;
  update pb_ai.kb_chunks set chunk = $kb${"id": "quick-reference-3", "url": "https://open-exam-prep.com/study-guides/ca-water-operator/distribution-disinfection-quality/main-disinfection-c651", "text": "Common water main numbers (check your spec, which governs). Hydrostatic test: AWWA C600 per U.S. Pipe, at least 1.25 times working pressure at the high point and 1.5 times at the low point; some utilities use 150 psi or 1.5 times working pressure, others working pressure plus 100 psi; hold at least 2 hours. Allowable make-up water L (gallons per hour) = S x D x square root of P / 148,000; for 1,000 ft of 8 inch at 150 psi, about 0.66 gal/hr. Disinfection (AWWA C651): continuous feed at least 25 mg/L, held 24 hours, at least 10 mg/L remaining; slug at least 100 mg/L for 3 hours; tablet about 25 mg/L for 24 hours. Bac-T samples every 1,200 ft plus end and branches, two consecutive acceptable sets. Flush before chlorinating at 3.0 ft per second or more (AWWA C651-14 Sec. 4.4.2; the 2005 edition said 2.5 ft per second, which is about 390 gpm in 8 inch).", "title": "Quick reference: water main test numbers", "topic": "Quick reference numbers", "source": "AWWA C600 (U.S. Pipe), utility specs, AWWA C651 summary", "confidence": "high", "supersedes": "quick-reference-3"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 1897 and chunk->>'id' = $kb$quick-reference-3$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 1897; end if;
  update pb_ai.kb_chunks set chunk = $kb${"id": "quick-reference-4", "url": "https://www.osha.gov/trenching-excavation", "text": "Key OSHA trench numbers (plain language; the regulation governs). Protective system required at 5 ft deep or more (unless stable rock), and in shallower trenches if a cave-in is possible. Over 20 ft the rule requires a system designed by a registered professional engineer, and OSHA's guidance treats 20 ft and deeper the same way, so plan on an engineer at 20 ft. Ladder or other exit required at 4 ft deep or more, within 25 ft of lateral travel. Spoil and equipment at least 2 ft from the edge. Atmosphere testing over 4 ft deep where hazardous atmosphere could exist: oxygen below 19.5% is deficient; flammable gas must stay below 20% of LFL. Maximum slopes: Type A 3/4 to 1; Type B 1 to 1; Type C 1-1/2 to 1. Shield: may dig up to 2 ft below the box only if rated for full depth with no soil loss. Daily inspection by the competent person, and after rain. State plans can be stricter: Washington requires a protective system at 4 ft (WAC 296-155-657), and California also needs a Cal/OSHA permit at 5 ft (8 CCR 341).", "title": "Quick reference: trench safety numbers", "topic": "Quick reference numbers", "source": "OSHA 29 CFR 1926.650-652", "confidence": "high"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 1898 and chunk->>'id' = $kb$quick-reference-4$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 1898; end if;
  update pb_ai.kb_chunks set chunk = $kb${"id": "quick-reference-5", "url": "https://iowaonecall.com/wp-content/uploads/2024/08/iaoc-excavator-manual-2024.pdf", "text": "APWA locate colors: red electric; yellow gas, oil, steam; orange communications; blue potable water; purple reclaimed water and irrigation; green sewer and storm drain; white proposed excavation; pink temporary survey marks. Tolerance zone: commonly 18 inches each side of the marked facility or 24 inches, by state law; hand dig or vacuum excavate inside it. Typical notice: 2 to 3 business days (Iowa 48 hours excluding weekends and holidays). Tickets expire (Iowa: 25 calendar days after the wait period). Locators don't mark depth. Check your state's one-call law.", "title": "Quick reference: locate color codes and tolerance zone", "topic": "Quick reference numbers", "source": "APWA color code; Iowa One Call manual", "confidence": "high"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 1899 and chunk->>'id' = $kb$quick-reference-5$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 1899; end if;
  update pb_ai.kb_chunks set chunk = $kb${"id": "quick-reference-8", "text": "Joint deflection numbers to know (always check the maker for your joint). Ductile iron push-on (McWane chart, 18 ft lengths): 3 to 30 inch, 5 degrees, about 19 inches offset, about 205 ft radius; 36 inch, 4 degrees, about 15 inches, about 260 ft radius. PVC: varies by maker; Westlake lists 1 degree for integral bell joints and 0.5 degree per side on their restrained coupling; solvent-weld joints none. Offset per degree (Uni-Bell): 4.2 inches on a 20 ft stick, 2.1 inches on 10 ft. Radius (ft) = 57.3 x length (ft) / degrees per joint. 1 degree vertical = about 1.75% slope change. Assemble joints straight and fully homed, then deflect. Gravity sewer is normally laid straight between manholes.", "title": "Quick reference: joint deflection", "topic": "Quick reference numbers", "source": "McWane Ductile; Westlake; Uni-Bell", "confidence": "high"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 1902 and chunk->>'id' = $kb$quick-reference-8$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 1902; end if;
  update pb_ai.kb_chunks set chunk = $kb${"id": "quick-reference-12", "url": "https://www.law.cornell.edu/regulations/virginia/12VAC5-590-1150", "text": "Common separation rules (Ten States approach, as in Virginia 12VAC5-590-1150): water mains at least 10 ft horizontally from sanitary sewers and manholes, edge to edge. Crossings: at least 18 inches vertical between bottom of water main and top of sewer, water over sewer. If the 10 ft or 18 inch can't be met: sewer built of water-main-grade pipe and pressure tested, or approved encasement; at crossings, water-grade sewer pipe 10 ft each side; if water goes under sewer, 18 inches clearance, support the sewer and center a full length of water pipe on the crossing. No water pipe through or touching a sewer manhole. States differ; check yours.", "title": "Quick reference: water and sewer separation", "topic": "Quick reference numbers", "source": "Virginia 12VAC5-590-1150", "confidence": "high"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 1906 and chunk->>'id' = $kb$quick-reference-12$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 1906; end if;
  update pb_ai.kb_chunks set chunk = $kb${"id": "testing-water-8", "url": "https://open-exam-prep.com/study-guides/ca-water-operator/distribution-disinfection-quality/main-disinfection-c651", "text": "New mains are flushed before disinfection (except with the tablet method) to remove dirt, and after disinfection to remove heavily chlorinated water. AWWA C651-14 (Sec. 4.4.2) calls for flushing at 3.0 ft per second or more; the 2005 edition said about 2.5 ft per second, and specs written on it still say that. Flow needed for 3.0 ft per second (computed from pipe area): 4 inch about 120 gpm; 6 inch about 265 gpm; 8 inch about 470 gpm; 10 inch about 735 gpm; 12 inch about 1,060 gpm; 16 inch about 1,880 gpm (at 2.5 ft per second, 8 inch is about 390 gpm). Your spec or the water agency governs. A single 2-1/2 inch hydrant outlet may not deliver enough for larger mains, so use more outlets or the pumper nozzle. Flush until the water runs clear and, after disinfection, until the chlorine residual is no higher than the normal distribution system level. Control discharge to prevent erosion and dechlorinate per permit. Flow values are computed from area times velocity.", "title": "Disinfection: flushing velocity and flow", "topic": "Testing: water main pressure test and disinfection", "source": "AWWA C651 summary, Open Exam Prep water operator study guide", "confidence": "medium", "supersedes": "testing-water-8"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 1955 and chunk->>'id' = $kb$testing-water-8$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 1955; end if;
  update pb_ai.kb_chunks set chunk = $kb${"id": "test-1", "text": "Ductile iron (AWWA C600) and PVC (AWWA C605) water mains are pressure tested after backfill (or with joints exposed if the spec allows): fill slowly, bleed all air at hydrants, air valves and taps, raise to the test pressure (commonly 1.5 times working pressure or 150 psi minimum, or the agency's rule, such as Greenbook's working pressure plus 50 psi) and hold for at least 2 hours (Greenbook: 4 hours). Measure the makeup water pumped in to keep the pressure. Allowable leakage in gallons per hour L = S x D x sqrt(P) / 148,000, with S = length tested in ft, D = nominal diameter in inches, P = average test pressure in psi. Example: 1,000 ft of 8 in at 150 psi allows about 0.66 gal/hr. Pressure that keeps dropping usually means air in the line, a valve passing, or a leaking joint or tap.", "title": "Water main pressure and leakage test (AWWA C600 / C605)", "topic": "Testing water and sewer lines", "source": "AWWA C600 and C605; Greenbook 306-8.9.2"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 2363 and chunk->>'id' = $kb$std-awwa-c600-hydro-1$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 2363; end if;
  update pb_ai.kb_chunks set chunk = $kb${"id": "test-2", "text": "Plug both ends, pressurize to about 4.0 psi, let it stabilize, then start timing at 3.5 psi and record the time for a 1.0 psi drop (some specs time a 0.5 psi drop for half the time). Minimum times for a 1.0 psi drop (ASTM F1417 / Uni-Bell): 4 in 1:53; 6 in 2:50; 8 in 3:47; 10 in 4:43; 12 in 5:40; 15 in 7:05. These apply up to about 597, 398, 298, 239, 199 and 159 ft; for longer runs the time is 0.190 x L (4 in), 0.427 x L (6 in), 0.760 x L (8 in), 1.187 x L (10 in), 1.709 x L (12 in), 2.671 x L (15 in) seconds. Raise the test pressure by groundwater head (0.43 psi per ft of water above the pipe). Never stand in front of a plug under pressure, use a relief valve, and never exceed the spec maximum (Greenbook: 5 psi). The agency's spec (Greenbook times 2.5 to 1.5 psi) governs.", "title": "Sewer low-pressure air test (ASTM F1417 for plastic pipe)", "topic": "Testing water and sewer lines", "source": "ASTM F1417; Uni-Bell PVC Pipe Association; Greenbook 306-7.8.2.4"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 2364 and chunk->>'id' = $kb$std-astm-airtest-1$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 2364; end if;
  update pb_ai.kb_chunks set chunk = $kb${"id": "test-3", "text": "Keep pipe clean during laying, then disinfect before connecting to the system. AWWA C651 methods: continuous feed (water with at least 25 mg/L free chlorine fills the main, held 24 hours, ending with at least 10 mg/L), tablet (25 mg/L, 24 hours, water above 41 F), or slug (100 mg/L passed through for at least 3 hours). Agency specs can be stronger (Greenbook: 50 to 100 mg/L, 24 hours, 25 mg/L residual). Flush until the water is at system chlorine levels, dechlorinate the flush water before discharge, then take bacteriological (bac-T) samples: two sets that both pass, taken as the spec says (AWWA C651-14: a second set at least 16 hours after the first, or let the main sit 16 hours and take two sets 15 minutes apart; specs written on the 2005 edition say 24 hours apart), or per the agency; all must show no coliform. Don't connect until samples pass, and resample if the main isn't put in service in time.", "title": "Water main disinfection and bac-T samples (AWWA C651)", "topic": "Testing water and sewer lines", "source": "AWWA C651; Greenbook 306-8.9.4", "supersedes": "test-3"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 2365 and chunk->>'id' = $kb$test-3$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 2365; end if;
  update pb_ai.kb_chunks set chunk = $kb${"id": "thr-1", "text": "Water pressure pushes on every bend, tee, reducer, dead end and valve. Thrust on a bend T = 2 x P x A x sin(angle / 2); at a dead end or tee branch T = P x A; P = test pressure in psi (use the test pressure, not working), A = area of the pipe's outside diameter in square inches. Bearing area of the block = T x safety factor / allowable soil bearing (psf). Example: 8 in C900 (OD 9.05 in, A = 64.3 sq in) at 200 psi: a 90 degree bend pushes about 18,200 lb; a 45 about 9,850 lb; a dead end about 12,900 lb. In soil allowing 2,000 psf, the 90 needs about 9.1 sq ft of bearing face (before any safety factor). Typical allowable bearing (check the geotech or agency standard): soft clay about 500 to 1,000 psf, sand about 2,000, gravel and hard clay 3,000 to 4,000 psf.", "title": "How thrust works and how a block is sized", "topic": "Thrust blocks and restraint", "source": "AWWA M41 (ductile iron) and M23 (PVC) thrust design; standard practice"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 2370 and chunk->>'id' = $kb$thr-1$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 2370; end if;
  update pb_ai.kb_chunks set chunk = $kb${"id": "mfr-dipra-test-1", "url": "https://pe.mcwane.com/upl/downloads/dipra/dip-installation-guide-ab36416e.pdf", "kind": "summary", "text": "Testing a new ductile iron water main, summarized from the DIPRA Installation Guide (revised May 2015), which follows AWWA C600 and C651. Pressure test: at least 1.5 times the working pressure at the lowest point of the section, held for at least 2 hours (150 psi working means a 225 psi test). Measure the make-up water needed to hold pressure; examples of the testing allowance at 150 psi are about 0.50 gallon per hour per 1,000 feet of 6 inch and 0.99 for 12 inch. Brace or restrain temporary plugs and caps. Flush at 3.0 feet per second: roughly 400 gpm for a 6 inch main and 1,060 gpm for a 12 inch. Chlorination (AWWA C651): tablet method, granules at the start and every 500 feet and 5-gram tablets at joints, fill slowly at 1 foot per second or less, hold 24 hours (48 hours if the water is colder than 41 F), about 25 mg/L; continuous feed, at least 25 mg/L going in and at least 10 mg/L left after 24 hours; slug method, at least 100 mg/L for at least 3 hours, start over if it drops below 50 mg/L. Flush the strong chlorine out within about a day, dechlorinate where the discharge rule requires it, then take bacteria samples. The water agency's spec governs.", "tier": "core", "state": "US", "title": "Water main pressure test, flushing and chlorination basics (DIPRA guide, AWWA C600 and C651)", "topic": "Spec books: pipe testing and inspection (air, water, mandrel, video)", "source": "Ductile Iron Pipe Research Association (DIPRA), Installation Guide for Ductile Iron Pipe, revised May 2015, hosted by McWane (our summary; read 2026-11-20)", "checked": "2026-11-20", "edition": "2015", "license": "summary", "confidence": "high"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 3131 and chunk->>'id' = $kb$mfr-dipra-test-1$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 3131; end if;
  update pb_ai.kb_chunks set chunk = $kb${"id": "mfr-dipra-thrust-1", "url": "https://pe.mcwane.com/upl/downloads/dipra/dip-installation-guide-ab36416e.pdf", "kind": "summary", "text": "Thrust restraint basics, summarized from the DIPRA Installation Guide for Ductile Iron Pipe (revised May 2015). Water pressure pushes on every bend, tee, reducer, valve and dead end. Example thrust at 100 psi: a 12 inch 90 degree bend pushes about 19,353 lb and a 12 inch dead end about 13,685 lb; thrust scales straight with pressure, so use test pressure, not working pressure. Example soil bearing values at 4 feet deep (Table 8): muck 0, sand about 4,000 lb per square foot, hard clay about 9,000. Common practice is block bearing area = thrust divided by the allowable soil bearing, poured against undisturbed soil. Blocks are concrete of at least 2,000 psi, cured at least five days before testing. Mechanical joints by themselves hold no thrust. Restrained joints (or wedge-action glands) are used instead of blocks where space is tight or the soil behind the block may be dug out later; the restrained length comes from the engineer or the agency table. Always build what the plans or the agency thrust block detail shows; these numbers are examples, not a design.", "tier": "core", "state": "US", "title": "Thrust blocks at bends and dead ends: forces, soil bearing values, how strong the concrete (DIPRA guide)", "topic": "Thrust blocks and restrained joints", "source": "Ductile Iron Pipe Research Association (DIPRA), Installation Guide for Ductile Iron Pipe, revised May 2015, hosted by McWane (our summary; read 2026-11-20)", "checked": "2026-11-20", "edition": "2015", "license": "summary", "confidence": "medium"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 3132 and chunk->>'id' = $kb$mfr-dipra-thrust-1$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 3132; end if;
  update pb_ai.kb_versions v set n = c.n, counts = c.counts
    from (select sum(k)::int as n, jsonb_object_agg(lib, k) as counts from (select lib, count(*)::int as k from pb_ai.kb_chunks where version = 'b3e91f6c47d2' group by lib) x) c
   where v.version = 'b3e91f6c47d2';
  delete from pb_ai.kb_index_parts where version = 'b3e91f6c47d2';
  delete from pb_ai.kb_index where version = 'b3e91f6c47d2';
  select count(*), md5(string_agg(ord||':'||lib||':'||(chunk::text), '|' order by ord)) from pb_ai.kb_chunks where version = 'b3e91f6c47d2' into vn, vm;
  if vn <> 3247 or vm is distinct from 'f85b4d61df8e54abe6bd391f7317cbd7' then raise exception 'FAIL after rollback: % rows, md5 %', vn, vm; end if;
  raise notice 'ask_everyday 91_rollback: done, % rows, md5 %', vn, vm;
end $rb$;
commit;
